const fs = require('fs');

function main() {
  const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
  if (data.length === 0) return;

  const n = parseInt(data[0], 10);

  const prefix = Array.from({ length: 11 }, () => new Set());
  const suffix = Array.from({ length: 11 }, () => new Set());

  prefix[0].add('');
  suffix[0].add('');

  for (let i = 1; i <= n; i++) {
    const t = data[i];

    let invalid = false;

    for (let x = 0; x <= 10; x++) {
      const left = t.slice(0, x);
      const right = t.slice(x);

      if (suffix[x].has(left) && prefix[10 - x].has(right)) {
        invalid = true;
        break;
      }
    }

    if (invalid) {
      console.log(t);
      return;
    }

    for (let len = 1; len <= 10; len++) {
      prefix[len].add(t.slice(0, len));
      suffix[len].add(t.slice(10 - len));
    }
  }

  console.log('ok');
}

main();
